package com.tripnest.controller; import com.tripnest.dto.ApiDtos.AccommodationView; import com.tripnest.service.WishlistService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/wishlist") public class WishlistController { final WishlistService service; public WishlistController(WishlistService s){service=s;} @GetMapping public List<AccommodationView> list(Authentication a){return service.list(a.getName());} @PutMapping("/{accommodationId}") public Map<String,String> add(@PathVariable Long accommodationId,Authentication a){service.add(a.getName(),accommodationId);return Map.of("message","Saved to your wishlist.");} @DeleteMapping("/{accommodationId}") public Map<String,String> remove(@PathVariable Long accommodationId,Authentication a){service.remove(a.getName(),accommodationId);return Map.of("message","Removed from your wishlist.");} }
